    gdjs.RealTimeMP = {
        // --- Connection state ---
        socket: null,
        serverUrl: "",
        roomId: "",
        playerId: "",
        playerName: "",
        isHost: false,
        connectionStatus: "disconnected", // disconnected | connecting | connected | error
        lastError: "",

        // --- Room state ---
        roomPlayers: {},       // { playerId: { name, x, y, angle, data, ping, latency } }
        roomVariables: {},     // { key: value }
        customEvents: [],      // [ { name, senderId, data } ]
        chatMessages: [],      // [ { senderId, senderName, text, timestamp } ]
        playerCount: 0,

        // --- Object sync ---
        syncObjects: {},       // { objectName: { x, y, angle, scaleX, scaleY, visible, animation, zOrder, data } }

        // --- RPC queue ---
        rpcQueue: [],          // [ { name, args, senderId } ]

        // --- Ping / latency ---
        pingInterval: null,
        latency: 0,
        pingSentAt: 0,

        // --- Lobby ---
        lobbyRooms: [],        // [ { id, name, playerCount, maxPlayers, locked } ]

        // --- Bullet Sync ---
        bulletQueue: [],       // [ { objectName, x, y, angle, animation, senderId, timestamp } ]

        // --- Prediction / Reconciliation ---
        inputBuffer: [],

        // --- Timers ---
        tickInterval: null,
        syncRate: 50,  // ms

        // --- Flags ---
        justConnected: false,
        justDisconnected: false,
        justJoinedRoom: false,
        justLeftRoom: false,
        playerJustJoined: "",
        playerJustLeft: "",
        hostChanged: false,
        newHostId: "",

        // ============================================================
        _reset: function() {
            if (this.pingInterval) clearInterval(this.pingInterval);
            if (this.tickInterval) clearInterval(this.tickInterval);
            this.socket = null;
            this.connectionStatus = "disconnected";
            this.roomId = "";
            this.playerId = "";
            this.isHost = false;
            this.roomPlayers = {};
            this.roomVariables = {};
            this.customEvents = [];
            this.chatMessages = [];
            this.syncObjects = {};
            this.rpcQueue = [];
            this.lobbyRooms = [];
            this.playerCount = 0;
            // Reconnect cleanup: never let stale bullets, RPCs, custom events
            // or cached player state survive a reconnect.
            this.bulletQueue = [];
            this._currentBullet = null;
            this._receivedState = {};
            this.playerJustJoined = "";
            this.playerJustLeft = "";
            this.hostChanged = false;
            this.newHostId = "";
        },

        // ============================================================
        _send: function(msgObj) {
            if (this.socket && this.socket.readyState === WebSocket.OPEN) {
                this.socket.send(JSON.stringify(msgObj));
                return true;
            }
            return false;
        },

        // ============================================================
        _handleMessage: function(rawData) {
            let msg;
            try { msg = JSON.parse(rawData); } catch(e) { return; }
            const t = msg.type;

            if (t === "welcome") {
                this.playerId = msg.playerId;
                this.connectionStatus = "connected";
                this.justConnected = true;
                // start ping
                this.pingSentAt = Date.now();
                this._send({ type: "ping", t: this.pingSentAt });
                this.pingInterval = setInterval(() => {
                    this.pingSentAt = Date.now();
                    this._send({ type: "ping", t: this.pingSentAt });
                }, 2000);
            }
            else if (t === "pong") {
                this.latency = Math.round((Date.now() - msg.t) / 2);
                if (this.roomPlayers[this.playerId]) {
                    this.roomPlayers[this.playerId].latency = this.latency;
                }
            }
            else if (t === "room_joined") {
                this.roomId = msg.roomId;
                this.isHost = msg.isHost || false;
                this.roomPlayers = msg.players || {};
                this.roomVariables = msg.variables || {};
                this.playerCount = Object.keys(this.roomPlayers).length;
                this.justJoinedRoom = true;
            }
            else if (t === "room_left") {
                this.roomId = "";
                this.isHost = false;
                this.roomPlayers = {};
                this.roomVariables = {};
                this.playerCount = 0;
                this.justLeftRoom = true;
            }
            else if (t === "player_joined") {
                this.roomPlayers[msg.playerId] = msg.playerData || { name: msg.playerName || "", x:0, y:0, z:0, angle:0, data:{} };
                this.playerCount = Object.keys(this.roomPlayers).length;
                this.playerJustJoined = msg.playerId;
            }
            else if (t === "player_left") {
                delete this.roomPlayers[msg.playerId];
                delete this._receivedState[msg.playerId]; // Reconnect cleanup: drop stale player reference
                this.playerCount = Object.keys(this.roomPlayers).length;
                this.playerJustLeft = msg.playerId;
            }
            else if (t === "host_changed") {
                this.isHost = (msg.newHostId === this.playerId);
                this.newHostId = msg.newHostId;
                this.hostChanged = true;
            }
            else if (t === "state_sync") {
                // batch sync of all players
                const states = msg.states || {};
                for (const [pid, state] of Object.entries(states)) {
                    if (!this.roomPlayers[pid]) this.roomPlayers[pid] = {};
                    Object.assign(this.roomPlayers[pid], state);
                    this._receivedState[pid] = true; // Owner validation: real position confirmed
                }
            }
            else if (t === "player_state") {
                const pid = msg.playerId;
                if (!this.roomPlayers[pid]) this.roomPlayers[pid] = {};
                Object.assign(this.roomPlayers[pid], msg.state);
                this._receivedState[pid] = true; // Owner validation: real position confirmed
            }
            else if (t === "object_sync") {
                const objs = msg.objects || {};
                for (const [objId, objState] of Object.entries(objs)) {
                    this.syncObjects[objId] = objState;
                }
            }
            else if (t === "room_variable") {
                this.roomVariables[msg.key] = msg.value;
            }
            else if (t === "custom_event") {
                this.customEvents.push({ name: msg.name, senderId: msg.senderId, data: msg.data || "" });
            }
            else if (t === "bullet_spawn") {
                this.bulletQueue.push({ objectName: msg.objectName, x: msg.x, y: msg.y, angle: msg.angle, animation: msg.animation || "", senderId: msg.senderId, timestamp: msg.timestamp || Date.now() });
            }
            else if (t === "rpc") {
                this.rpcQueue.push({ name: msg.name, args: msg.args || [], senderId: msg.senderId });
            }
            else if (t === "chat") {
                if (msg.senderId !== this.playerId) {
                    this.chatMessages.push({ senderId: msg.senderId, senderName: msg.senderName || "", text: msg.text, timestamp: Date.now() });
                    if (this.chatMessages.length > 100) this.chatMessages.shift();
                }
            }
            else if (t === "lobby_list") {
                this.lobbyRooms = msg.rooms || [];
            }
            else if (t === "error") {
                this.lastError = msg.message || "Unknown error";
                this.connectionStatus = "error";
            }
            else if (t === "kicked") {
                this.lastError = "Kicked: " + (msg.reason || "");
                // Reconnect cleanup: purge everything pending so a future
                // reconnect never replays stale bullets/RPCs/events.
                this.bulletQueue = [];
                this.rpcQueue = [];
                this.customEvents = [];
                this._currentBullet = null;
                if (this.socket) this.socket.close();
            }
        }
    };
}

