function renderRooms() {
    listDiv.innerHTML = '';
    const rooms = mp.lobbyRooms || [];
    if (rooms.length === 0) {
        listDiv.innerHTML = '<div id="rtmp-lobby-empty">No rooms available. Be the first — create one!</div>';
        return;
    }
    rooms.forEach((room, idx) => {
        const row = document.createElement('div');
        row.className = 'rtmp-room-row';
        const nameEl = document.createElement('span');
        nameEl.className = 'rtmp-room-name';
        nameEl.textContent = room.name || room.id;
        if (idx === 0) nameEl.style.fontWeight = '700';
        row.appendChild(nameEl);

        const playersEl = document.createElement('span');
        playersEl.className = 'rtmp-room-players';
        playersEl.textContent = `${room.playerCount || 0}/${room.maxPlayers || '?'}`;
        row.appendChild(playersEl);

        const lockEl = document.createElement('span');
        lockEl.className = 'rtmp-room-lock';
        lockEl.textContent = room.locked ? '🔒' : '';
        row.appendChild(lockEl);

        const joinBtn = document.createElement('button');
        joinBtn.className = 'rtmp-join-btn';
        joinBtn.textContent = 'Join';
        const isFull = (room.playerCount || 0) >= (room.maxPlayers || 99);
        if (isFull) { joinBtn.disabled = true; joinBtn.textContent = 'Full'; }
        else {
            if (idx !== 0) joinBtn.style.background = '#888';
            joinBtn.onclick = () => {
                if (room.locked) {
                    showPasswordModal(room.id);
                } else {
                    mp._send({ type: 'join_room', roomId: room.id, password: '' });
                    overlay.remove();
                    document.getElementById('rtmp-lobby-style')?.remove();
                }
            };
        }
        row.appendChild(joinBtn);
        listDiv.appendChild(row);
    });
}

