// === Render messages ===
let lastRenderedCount = -1;
function formatTime(ts) {
    const d = new Date(ts);
    return d.getHours().toString().padStart(2,'0') + ':' + d.getMinutes().toString().padStart(2,'0');
}

function renderMessages() {
    const msgs = mp.chatMessages || [];
    if (msgs.length === lastRenderedCount) return;
    lastRenderedCount = msgs.length;

    if (msgs.length === 0) {
        messagesDiv.innerHTML = '<div id="rtmp-chat-empty">No messages yet. Say hello! 👋</div>';
        return;
    }

    messagesDiv.innerHTML = '';
    msgs.forEach((msg) => {
        const isMe = msg.senderId === mp.playerId;
        const div = document.createElement('div');
        div.className = 'rtmp-msg ' + (isMe ? 'mine' : 'other');

        const nameEl = document.createElement('div');
        nameEl.className = 'rtmp-msg-name';
        nameEl.textContent = isMe ? 'You' : (msg.senderName || msg.senderId);

        const bubble = document.createElement('div');
        bubble.className = 'rtmp-msg-bubble';
        bubble.textContent = msg.text || '';

        const timeEl = document.createElement('div');
        timeEl.className = 'rtmp-msg-time';
        timeEl.textContent = msg.timestamp ? formatTime(msg.timestamp) : '';

        div.appendChild(nameEl);
        div.appendChild(bubble);
        div.appendChild(timeEl);
        messagesDiv.appendChild(div);
