// === Send message ===
const CHAT_COOLDOWN_MS = 1500;   // 1.5s between messages
const CHAT_MAX_BURST = 4;         // max 4 messages then mute
const CHAT_BURST_WINDOW = 6000;  // within 6 seconds
if (!mp._chatState) mp._chatState = { lastSent: 0, burst: [], mutedUntil: 0 };

function sendMsg() {
    const input = document.getElementById('rtmp-chat-input');
    const text = (input.value || '').trim();
    if (!text) return;
    if (!mp.roomId) return;

    const now = Date.now();
    const cs = mp._chatState;

    // Check mute
    if (now < cs.mutedUntil) {
        const secs = Math.ceil((cs.mutedUntil - now) / 1000);
        errorFlash(`⛔ Too fast! Wait ${secs}s`);
        return;
    }

    // Check cooldown
    if (now - cs.lastSent < CHAT_COOLDOWN_MS) {
        errorFlash('⏳ Slow down...');
        return;
    }

    // Track burst
    cs.burst = cs.burst.filter(t => now - t < CHAT_BURST_WINDOW);
    cs.burst.push(now);
    if (cs.burst.length >= CHAT_MAX_BURST) {
        cs.mutedUntil = now + 8000;
        cs.burst = [];
        errorFlash('🚫 Muted for 8s (spam detected)');
        return;
    }

    cs.lastSent = now;
    mp._send({ type: 'chat', text, senderName: mp.playerName });
    mp.chatMessages.push({ senderId: mp.playerId, senderName: mp.playerName, text, timestamp: now });
    if (mp.chatMessages.length > 100) mp.chatMessages.shift();
    input.value = '';
    lastRenderedCount = -1;
    renderMessages();
}

function errorFlash(msg) {
    let el = document.getElementById('rtmp-chat-error');
    if (!el) {
        el = document.createElement('div');
        el.id = 'rtmp-chat-error';
        el.style.cssText = 'text-align:center;font-size:11px;color:#f87171;padding:4px 0;min-height:16px;';
        const inputRow = document.getElementById('rtmp-chat-input-row');
        inputRow && inputRow.parentNode.insertBefore(el, inputRow);
    }
    el.textContent = msg;
    clearTimeout(el._t);
    el._t = setTimeout(() => { el.textContent = ''; }, 2500);
}

document.getElementById('rtmp-chat-send').onclick = sendMsg;
document.getElementById('rtmp-chat-input').addEventListener('keydown', (e) => {
    if (e.key === 'Enter') { e.preventDefault(); sendMsg(); }
});

