});

const mp = gdjs.RealTimeMP;
if (!mp || !mp.roomId) return;

const playerObjName  = eventsFunctionContext.getArgument('playerObject');
const otherObjName   = eventsFunctionContext.getArgument('otherObject');
const syncAnim       = eventsFunctionContext.getArgument('syncAnimation') === "true" || eventsFunctionContext.getArgument('syncAnimation') === true || String(eventsFunctionContext.getArgument('syncAnimation')) === "1";
const syncFlip       = eventsFunctionContext.getArgument('syncFlip') === "true" || eventsFunctionContext.getArgument('syncFlip') === true || String(eventsFunctionContext.getArgument('syncFlip')) === "1";
const syncScale      = eventsFunctionContext.getArgument('syncScale') === "true" || eventsFunctionContext.getArgument('syncScale') === true || String(eventsFunctionContext.getArgument('syncScale')) === "1";

// ── SEND MY STATE ────────────────────────────────────────────────────
const myObjs = runtimeScene.getObjects(playerObjName);
if (myObjs.length > 0) {
    const p = myObjs[0];
    const state = {
        x: p.getX(),
        y: p.getY(),
        z: (p.getZ ? p.getZ() : 0),
        angle: p.getAngle(),
        name: mp.playerName
    };
    if (syncFlip)  { state.flipX = p.isFlippedX(); state.flipY = p.isFlippedY(); }
    if (syncAnim) {
        // Send index — reliable across GDevelop 3D objects
        state.animIdx = p.getAnimationIndex ? p.getAnimationIndex() : 0;
        state.anim3d  = p.getAnimationName  ? p.getAnimationName()  : '';
    }
    if (syncScale) {
        // Send width/height as absolute pixels — works regardless of GDevelop version
        state.w = p.getWidth();
        state.h = p.getHeight();
    }
    mp._send({ type: "player_state", state });
}

// ── SPAWN OTHER PLAYERS ──────────────────────────────────────────────
// Self-hit protection / Owner validation: never spawn (or re-use) an
// OtherPlayer for a player whose real position we haven't received yet.
// Without this, a newly (re)joined player is briefly represented at the
// server's default (0,0) placeholder position, which can overlap a
// freshly-fired bullet and cause a false "self hit" right after reconnect.
if (!mp._receivedState) mp._receivedState = {};
for (const pid of Object.keys(mp.roomPlayers)) {
    if (pid === mp.playerId) continue; // Self-hit protection: never create an OtherPlayer for myself
    if (!mp._receivedState[pid]) continue; // Owner validation: wait for a real position update first
    let found = false;
    for (const o of runtimeScene.getObjects(otherObjName)) {
        if (o.getVariables().get('pid').getAsString() === pid) { found = true; break; }
    }
    if (!found) {
        // Prevent duplicate OtherPlayer creation: we already checked above
        // that no object with this pid exists before creating a new one.
        const o = runtimeScene.createObject(otherObjName);
        if (o) {
            o.getVariables().get('pid').setString(pid);
            const rp = mp.roomPlayers[pid];
            if (rp) {
                o.setX(rp.x || 0);
                o.setY(rp.y || 0);
                if (o.setZ && rp.z !== undefined) o.setZ(rp.z);
                if (rp.animIdx !== undefined && o.setAnimationIndex) {
                    o.setAnimationIndex(rp.animIdx);
                }
            }
        }
    }
}

// ── UPDATE OTHER PLAYERS ─────────────────────────────────────────────
for (const obj of runtimeScene.getObjects(otherObjName)) {
    const pid = obj.getVariables().get('pid').getAsString();
    const rp = mp.roomPlayers[pid];
    if (!rp) continue;
    obj.setX(rp.x || 0);
    obj.setY(rp.y || 0);
    if (obj.setZ && rp.z !== undefined) obj.setZ(rp.z);
    obj.setAngle(rp.angle || 0);
    if (syncFlip) {
        if (rp.flipX !== undefined) obj.flipX(rp.flipX);
        if (rp.flipY !== undefined) obj.flipY(rp.flipY);
    }
    if (syncAnim) {
        // Apply index every frame — setAnimationIndex won't restart if same index
        if (rp.animIdx !== undefined && obj.setAnimationIndex) {
            obj.setAnimationIndex(rp.animIdx);
        }
    }
    if (syncScale) {
        // Apply width/height directly — avoids setScaleX/setScaleY compatibility issues
        if (rp.w !== undefined && rp.w > 0) obj.setWidth(rp.w);
        if (rp.h !== undefined && rp.h > 0) obj.setHeight(rp.h);
    }
}

// ── REMOVE DISCONNECTED PLAYERS ──────────────────────────────────────
// Reconnect cleanup: also drop any OtherPlayer whose pid is no longer a
// connected room member (covers kicks, disconnects and stale duplicates).
if (mp.playerJustLeft !== "") {
    for (const obj of runtimeScene.getObjects(otherObjName)) {
        if (obj.getVariables().get('pid').getAsString() === mp.playerJustLeft)
            obj.deleteFromScene(runtimeScene);
    }
}
for (const obj of runtimeScene.getObjects(otherObjName)) {
    const pid = obj.getVariables().get('pid').getAsString();
    if (pid && !mp.roomPlayers[pid]) {
        obj.deleteFromScene(runtimeScene); // Reconnect cleanup: stale player reference no longer in room
    }
}

