const filterName = eventsFunctionContext.getArgument("objectName");
const idx = mp.bulletQueue.findIndex(b => !filterName || b.objectName === filterName);
if (idx === -1) { eventsFunctionContext.returnValue = false; return; }
// Store current bullet for expressions
mp._currentBullet = mp.bulletQueue.splice(idx, 1)[0];

// Owner validation: permanently stamp the just-created remote bullet with
// the original shooter's player ID (whoever fired it on their own game),
// so this client's collision checks can also tell who owns it.
const remoteBulletObjs = eventsFunctionContext.getObjects("bulletObject");
