const objects = eventsFunctionContext.getObjects("object");
const targetPid = eventsFunctionContext.getArgument("playerId");
for (let i = objects.length - 1; i >= 0; i--) {
    const v = objects[i].getVariables().get('pid');
    const pid = v ? v.getAsString() : "";
    if (pid !== targetPid) {
        objects.splice(i, 1);
    }
}
eventsFunctionContext.returnValue = objects.length > 0;

// Owner validation / Self-hit protection
const mp = gdjs.RealTimeMP;
const bulletObjs = eventsFunctionContext.getObjects("bulletObject");
const targetObjs = eventsFunctionContext.getObjects("targetObject");
if (!mp || bulletObjs.length === 0 || targetObjs.length === 0) {
    eventsFunctionContext.returnValue = false;
    return;
}
let valid = false;
for (const b of bulletObjs) {
    const ownerVar = b.getVariables().get("pid");
    const ownerPid = ownerVar ? ownerVar.getAsString() : "";
    for (const t of targetObjs) {
        const targetVar = t.getVariables().get("pid");
        const targetPid = targetVar ? targetVar.getAsString() : "";
        if (!targetPid) continue;                     // target not tagged yet -> not valid
        if (!mp.roomPlayers || !mp.roomPlayers[targetPid]) continue; // target no longer connected -> not valid
        if (ownerPid && ownerPid === targetPid) continue; // Self-hit protection: same owner -> not valid
        valid = true;
    }
}
eventsFunctionContext.returnValue = valid;
